import * as issueService from "@/server/services/issue-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import { issueParticipantsSchema } from "@/schemas/comment";

let cleanup: () => void;
let a: Tenant;
let b: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  a = await createTenant("parta");
  b = await createTenant("partb");
});
afterAll(() => cleanup());

describe("participants", () => {
  it("works", async () => {
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "x" }));
    expect(await commentService.getIssueParticipants(a.actors.viewer, a.org.id, issue.id)).toEqual([a.actors.member.userId]);
    const c = await commentService.createComment(a.actors.admin, { orgId: a.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] });
    await commentService.createComment(a.actors.owner, { orgId: a.org.id, issueId: issue.id, body: "reply", parentId: c.id, mentionedUserIds: [] });
    await commentService.createComment(a.actors.owner, { orgId: a.org.id, issueId: issue.id, body: "again", parentId: null, mentionedUserIds: [] });
    const got = await commentService.getIssueParticipants(a.actors.viewer, a.org.id, issue.id);
    expect([...got].sort()).toEqual([a.actors.member.userId, a.actors.admin.userId, a.actors.owner.userId].sort());
    await commentService.deleteComment(a.actors.admin, { orgId: a.org.id, commentId: c.id });
    const got2 = await commentService.getIssueParticipants(a.actors.viewer, a.org.id, issue.id);
    expect([...got2].sort()).toEqual([a.actors.member.userId, a.actors.owner.userId].sort());
    const m = await memberRepo.findMember(a.org.id, a.actors.member.userId);
